def build_text(df: pd.DataFrame) -> pd.Series:
    columns = [
        "Creator",
        "Creator Detail",
        "Summary",
        "Description",
    ]

    text = df[columns[0]].fillna("").astype(str)

    for column in columns[1:]:
        text = text + " " + df[column].fillna("").astype(str)

    return text.str.strip()

